(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(y * 0.012 + t * 0.2) * 20 + Math.cos((x + y) * 0.008 - t * 0.15) * 12;
  const warp1y = Math.cos(x * 0.013 - t * 0.18) * 20 + Math.sin((x - y) * 0.009 + t * 0.22) * 12;
  const warp2x = Math.sin((y * 0.02 + x * 0.01) + t * 0.35) * 8;
  const warp2y = Math.cos((x * 0.02 - y * 0.01) - t * 0.3) * 8;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.1, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.4, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*65, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*100, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.08, 2.0, 0.95],
    [60+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+4)*50, 0.13, 1.4, 0.8],
    [420+Math.cos(t*0.42+2)*80, 220+Math.sin(t*0.58+1)*60, 0.075, 2.5, 1.15]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.7) * w;
    wS += Math.sin(d*f*0.4 - t*sp*0.3 + 3.1) * w * 0.5;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, cross = wS/n;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*0.95);
  const bg3 = Math.sin((sx+sy)*0.11+t*2.2)*0.3;
  const bg4 = Math.sin((sx-sy)*0.09-t*1.8)*0.3;
  const bg5 = Math.sin(sx*0.06+sy*0.04-t*1.4)*0.2;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.038+ang*4.5-t*1.05);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const lap = Math.sin(sx*0.18)*Math.sin(sy*0.18)*0.4 + Math.sin(sx*0.25+1.3)*Math.cos(sy*0.22-0.7)*0.3;
  const feed = 0.055 + 0.01*Math.sin(t*0.3);
  const kill = 0.062 + 0.008*Math.cos(t*0.25);
  const reaction = Math.tanh((act*(1+feed) - inh*(kill+cross*0.3) + bg*0.25 + spiral + lap*0.15)*2.5);
  const cell1 = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.095+t*0.8)*0.4)*1.8)*0.25;
  const cell2 = Math.tanh((Math.cos(sx*0.11+0.5)*Math.sin(sy*0.13-0.3) + Math.sin((sx-sy)*0.08-t*0.6)*0.3)*1.5)*0.15;
  const detail = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08*reaction;
  const blend = reaction*0.65 + cell1*0.2 + cell2*0.1 + detail;
  const v = blend*0.5+0.5;
  const pal = [
    [5, 12, 58], [12, 42, 98], [18, 78, 128], [25, 118, 135],
    [55, 155, 140], [140, 188, 110], [210, 195, 75], [235, 165, 65],
    [225, 120, 75], [195, 75, 80], [155, 45, 85], [105, 28, 78],
    [65, 18, 65], [30, 12, 58], [5, 12, 58]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx - i;
  const pulse = 0.85 + Math.sin(reaction*Math.PI*1.2)*0.15;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 1.0;
  const glow = Math.max(0, reaction)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*pulse*edge + glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*pulse*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*pulse*edge + glow*60)|0)
  ];
}
